/** Colour applied when an import creates a label. Matches `createLabelSchema`. */
const DEFAULT_LABEL_COLOR = "#94a3b8";

export type IssueImportRecord = {
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
};

export type ImportedIssueWrite = {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  readonly labelNames: readonly string[];
};

/** First-seen order, so a name repeated inside one row is attached once. */
function dedupeNames(names: readonly string[]): string[] {
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const name of names) {
    if (seen.has(name)) continue;
    seen.add(name);
    unique.push(name);
  }
  return unique;
}

export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;

  const parsed: unknown = JSON.parse(row.issueIds);
  const issueIds = Array.isArray(parsed)
    ? parsed.map((id) => brandId<IssueId>(String(id)))
    : [];

  return {
    projectId: brandId<ProjectId>(row.projectId),
    issueIds,
  };
}

/** Loads issues in the given id order, including labels in attachment order. */
export async function findIssuesInOrder(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<Issue[]> {
  if (issueIds.length === 0) return [];

  const db = getDb();
  const rows = db
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), inArray(issues.id, [...issueIds])),
    )
    .all();
  const byId = new Map(rows.map((row) => [row.id, row]));

  const labelRows = db
    .select({ issueId: issueLabels.issueId, labelId: issueLabels.labelId })
    .from(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        inArray(issueLabels.issueId, [...issueIds]),
      ),
    )
    .orderBy(sql`"issue_labels".rowid`)
    .all();

  const labelsByIssue = new Map<string, LabelId[]>();
  for (const labelRow of labelRows) {
    const bucket = labelsByIssue.get(labelRow.issueId) ?? [];
    bucket.push(brandId<LabelId>(labelRow.labelId));
    labelsByIssue.set(labelRow.issueId, bucket);
  }

  return issueIds.map((issueId) => {
    const row = byId.get(issueId);
    if (!row) throw new Error(`Issue ${issueId} not found`);
    return toIssue(row, labelsByIssue.get(issueId) ?? []);
  });
}

/**
 * Writes every row of one import, the labels it had to create, and the replay
 * ledger entry. The callback is synchronous so SQLite commits them together.
 */
export async function commitIssueImport(input: {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly authorId: UserId;
  readonly rows: readonly ImportedIssueWrite[];
}): Promise<readonly Issue[]> {
  const created = getDb().transaction((tx) => {
    const stamp = toIsoTimestamp(new Date());
    const labelIdByName = new Map<string, LabelId>();

    const existingLabels = tx
      .select()
      .from(labels)
      .where(orgPredicate(labels.orgId, input.orgId))
      .all();
    for (const label of existingLabels) {
      labelIdByName.set(label.name, brandId<LabelId>(label.id));
    }

    for (const row of input.rows) {
      for (const name of dedupeNames(row.labelNames)) {
        if (labelIdByName.has(name)) continue;
        const id = newId();
        tx.insert(labels)
          .values({
            id,
            orgId: input.orgId,
            name,
            color: DEFAULT_LABEL_COLOR,
            description: null,
            createdAt: stamp,
            updatedAt: stamp,
          })
          .run();
        labelIdByName.set(name, brandId<LabelId>(id));
      }
    }

    const maxRow = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();
    let nextNumber = (maxRow?.value ?? 0) + 1;

    const written: Issue[] = [];
    const writtenIds: string[] = [];

    for (const row of input.rows) {
      const labelIds = dedupeNames(row.labelNames).map((name) => {
        const labelId = labelIdByName.get(name);
        if (!labelId) throw new Error(`Label ${name} was not created`);
        return labelId;
      });

      const inserted = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId: input.orgId,
          projectId: input.projectId,
          number: nextNumber,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      nextNumber += 1;
      writtenIds.push(inserted.id);

      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId: inserted.id,
              labelId,
            })),
          )
          .run();
      }

      written.push(toIssue(inserted, labelIds));
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        projectId: input.projectId,
        importKey: input.importKey,
        issueIds: JSON.stringify(writtenIds),
        createdAt: stamp,
      })
      .run();

    return written;
  });

  return created;
}

