/** Colour applied when an import creates a label. Matches `createLabelSchema`. */
const DEFAULT_LABEL_COLOR = "#94a3b8";

export type IssueImportRecord = {
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
};

export type ImportedIssueWrite = {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  readonly labelNames: readonly string[];
};

/** First-seen order, so a name repeated inside one row is attached once. */
function dedupeNames(names: readonly string[]): string[] {
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const name of names) {
    if (seen.has(name)) continue;
    seen.add(name);
    unique.push(name);
  }
  return unique;
}

export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;

  const parsed: unknown = JSON.parse(row.issueIds);
  const issueIds = Array.isArray(parsed)
    ? parsed.map((id) => brandId<IssueId>(String(id)))
    : [];

  return {
    projectId: brandId<ProjectId>(row.projectId),
    issueIds,
  };
}

