import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { resetRateLimits } from "@/lib/rate-limit";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { importIssuesSchema } from "@/schemas/issue-import";
import { getDb, webhookDeliveries } from "@/server/db";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { listActivity } from "@/server/services/activity-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import { importIssues } from "@/server/services/issue-service";
import * as issueService from "@/server/services/issue-service";
import { listNotifications } from "@/server/services/notification-service";
import { archiveProject } from "@/server/services/project-service";
import { search } from "@/server/services/search-service";
import { getUsage, recomputeUsage } from "@/server/services/usage-service";
import { PermissionDeniedError } from "@/lib/permissions";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { ProjectId } from "@/types/common";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  tenant = await createTenant("import");
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

function parsed(rows: unknown[], extra: Record<string, unknown> = {}) {
  return importIssuesSchema.parse({
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    importKey: "import-key-1",
    rows,
    ...extra,
  });
}

describe("importIssues", () => {
  it("imports rows in order and replays without writing again", async () => {
    resetRateLimits();
    await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "Bug",
      color: "#94a3b8",
      description: "existing",
    });

    const firstIssue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Already there" }),
    );

    const input = parsed(
      [
        {
          title: "First imported",
          description: "alpha",
          status: "in_progress",
          priority: "high",
          assigneeEmail: "MEMBER@import.test",
          labels: ["Bug", "Bug", "fresh"],
          dueAt: "2026-11-01T00:00:00.000Z",
        },
        {
          title: "Second imported",
          assigneeEmail: "nobody@example.com",
          labels: ["fresh", "Other"],
        },
      ],
      { importKey: "batch-key-01" },
    );

    const created = await importIssues(tenant.actors.member, input);
    expect(created.replayed).toBe(false);
    expect(created.issues.map((issue) => issue.number)).toEqual([
      firstIssue.number + 1,
      firstIssue.number + 2,
    ]);
    expect(created.issues[0]).toMatchObject({
      title: "First imported",
      description: "alpha",
      status: "in_progress",
      priority: "high",
      authorId: tenant.actors.member.userId,
      assigneeId: tenant.userIds.member,
      parentId: null,
      estimate: null,
      dueAt: "2026-11-01T00:00:00.000Z",
    });
    expect(created.issues[1]?.assigneeId).toBeNull();

    const labels = await labelRepo.listLabels(tenant.org.id);
    const fresh = labels.filter((label) => label.name === "fresh");
    const other = labels.filter((label) => label.name === "Other");
    const bug = labels.filter((label) => label.name === "Bug");
    expect(fresh).toHaveLength(1);
    expect(other).toHaveLength(1);
    expect(bug).toHaveLength(1);
    expect(fresh[0]).toMatchObject({ color: "#94a3b8", description: null });
    expect(created.issues[0]?.labelIds).toEqual([bug[0]!.id, fresh[0]!.id]);
    expect(created.issues[1]?.labelIds).toEqual([fresh[0]!.id, other[0]!.id]);

    const next = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "After the batch" }),
    );
    expect(next.number).toBe(created.issues[1]!.number + 1);

    const replay = await importIssues(tenant.actors.member, {
      ...input,
      rows: [{ ...input.rows[0]!, title: "Changed title should be ignored" }],
    });
    expect(replay.replayed).toBe(true);
    expect(replay.issues.map((issue) => issue.id)).toEqual(
      created.issues.map((issue) => issue.id),
    );
    expect(replay.issues[0]?.title).toBe("First imported");

    const otherWorkspace = await createTenant("importb");
    const foreign = await importIssues(otherWorkspace.actors.member, {
      ...input,
      orgId: otherWorkspace.org.id,
      projectId: otherWorkspace.project.id,
    });
    expect(foreign.replayed).toBe(false);
    expect(foreign.issues[0]?.id).not.toBe(created.issues[0]?.id);

    const hits = await search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "First imported",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.items.some((hit) => hit.id === created.issues[0]?.id)).toBe(true);

    const usage = await getUsage(tenant.actors.owner, tenant.org.id);
    const recounted = await recomputeUsage(tenant.org.id);
    expect(usage.issuesUsed).toBe(recounted.issuesUsed);

    const audit = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["issues.imported"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "issues.imported",
      actorId: tenant.actors.member.userId,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 2, importKey: "batch-key-01" },
    });

    const createdAudit = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["issue.created"],
      limit: 25,
      cursor: null,
    });
    const importedIds = new Set(created.issues.map((issue) => issue.id));
    expect(createdAudit.items.some((row) => importedIds.has(row.subjectId as never))).toBe(
      false,
    );

    const notes = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(notes.items).toHaveLength(0);

    const deliveries = getDb()
      .select()
      .from(webhookDeliveries)
      .where(eq(webhookDeliveries.orgId, tenant.org.id))
      .all();
    expect(deliveries).toHaveLength(0);
  });

  it("refuses the batch without spending the key", async () => {
    resetRateLimits();
    const quotaTenant = await createTenant("importquota", "free");
    for (let number = 1; number <= 99; number += 1) {
      await import("@/server/repositories/issue-repository").then((repo) =>
        repo.insertIssue(
          issueInput(quotaTenant.org.id, quotaTenant.project.id, {
            title: `Seed ${number}`,
          }),
          quotaTenant.actors.member.userId,
          number,
        ),
      );
    }

    const over = importIssuesSchema.parse({
      orgId: quotaTenant.org.id,
      projectId: quotaTenant.project.id,
      importKey: "quota-key-01",
      rows: [{ title: "One more" }, { title: "Two more" }],
    });
    await expect(importIssues(quotaTenant.actors.member, over)).rejects.toThrow(
      /allows no more issues/,
    );
    const retry = importIssuesSchema.parse({
      ...over,
      rows: [{ title: "Only one" }],
    });
    const ok = await importIssues(quotaTenant.actors.member, retry);
    expect(ok.replayed).toBe(false);
    expect(ok.issues).toHaveLength(1);

    await expect(
      importIssues(tenant.actors.viewer, parsed([{ title: "Nope viewer" }], { importKey: "viewer-key1" })),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      importIssues(quotaTenant.actors.member, {
        ...retry,
        orgId: tenant.org.id,
        importKey: "scope-key-01",
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      importIssues(tenant.actors.member, {
        ...parsed([{ title: "Missing project" }], { importKey: "missing-key1" }),
        projectId: newId() as ProjectId,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const archived = await createTenant("importarch");
    await archiveProject(archived.actors.admin, archived.org.id, archived.project.id);
    await expect(
      importIssues(
        archived.actors.member,
        importIssuesSchema.parse({
          orgId: archived.org.id,
          projectId: archived.project.id,
          importKey: "archived-key",
          rows: [{ title: "Archived target" }],
        }),
      ),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("does not consume the key when the rate allowance is short", async () => {
    resetRateLimits();
    const rateTenant = await createTenant("importrate", "free");
    const rows = Array.from({ length: 61 }, (_, index) => ({
      title: `Rate row ${index + 10}`,
    }));
    const input = importIssuesSchema.parse({
      orgId: rateTenant.org.id,
      projectId: rateTenant.project.id,
      importKey: "rate-key-001",
      rows,
    });
    await expect(importIssues(rateTenant.actors.member, input)).rejects.toThrow(/rate limit/);
    const smaller = importIssuesSchema.parse({
      ...input,
      rows: rows.slice(0, 2),
    });
    const created = await importIssues(rateTenant.actors.member, smaller);
    expect(created.replayed).toBe(false);
    expect(created.issues).toHaveLength(2);
  });

  it("leaves removed members unassigned", async () => {
    resetRateLimits();
    const members = await memberRepo.listMembers({
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    const viewer = members.items.find((member) => member.userId === tenant.userIds.viewer);
    expect(viewer).toBeTruthy();
    await memberRepo.archiveMember(tenant.org.id, viewer!.id);

    const created = await importIssues(
      tenant.actors.member,
      parsed(
        [{ title: "Removed assignee", assigneeEmail: "viewer@import.test" }],
        { importKey: "removed-key1" },
      ),
    );
    expect(created.issues[0]?.assigneeId).toBeNull();
  });

  it("creates a webhook endpoint that must stay quiet", async () => {
    resetRateLimits();
    await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.com/hooks",
        eventTypes: ["issue.created", "issue.assigned", "issue.updated"],
      },
      "secret",
    );
    await importIssues(
      tenant.actors.member,
      parsed([{ title: "No webhook please", assigneeEmail: "admin@import.test" }], {
        importKey: "webhook-key1",
      }),
    );
    const deliveries = getDb()
      .select()
      .from(webhookDeliveries)
      .where(eq(webhookDeliveries.orgId, tenant.org.id))
      .all();
    expect(deliveries).toHaveLength(0);
  });
});

